
/* New: custom task input and card styles for black bg aesthetic */
.task-input-row {
  background: var(--input-bg);
  border-radius: 14px;
  box-shadow: 0 2px 16px #0b0c1088;
  border: 1px solid var(--border-color);
  padding: 9px 15px;
  display: flex;
  gap: 8px;
  margin: 0 auto 34px;
  min-height: 52px;
  max-width: 480px;
}
.task-input-row:focus-within {
  box-shadow: 0 2px 25px #25aef055;
}
.task-input {
  background: transparent;
  color: #d2e2f5;
  font-size: 1.09rem;
  border: none;
  outline: none;
  width: 100%;
  padding: 4px 8px;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.task-card {
  display: flex;
  align-items: center;
  background: var(--card-bg);
  border-radius: 13px;
  box-shadow: 0 1px 13px #1d233344;
  padding: 11px 15px;
  min-height: 44px;
  transition: box-shadow 0.14s, background 0.14s;
  border: 1px solid var(--border-color);
}

.task-card input[type="checkbox"] {
  accent-color: var(--accent);
  width: 22px;
  height: 22px;
  margin-right: 13px;
  cursor: pointer;
}

.task-text {
  flex: 1;
  font-size: 1.10rem;
  color: #f0fff9;
  font-family: 'Inter','Roboto','Helvetica','Arial',sans-serif;
  text-shadow: 0 2px 8px #10101955;
  transition: opacity 0.13s;
}

.task-text.completed {
  text-decoration: line-through;
  opacity: 0.52;
  color: #c4c8d2;
}

.del-btn {
  background: none;
  border: none;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--danger);
  font-size: 1.20rem;
  margin-left: 5px;
  cursor: pointer;
  transition: background 0.11s;
  outline: none;
}
.del-btn:focus,
.del-btn:hover {
  background: #34181822;
}

.task-footer {
  padding: 7px 0 20px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 1.02rem;
  letter-spacing: 0.01em;
}

@media (max-width: 700px) {
  .container {
    max-width: 97vw;
    padding: 0 7vw;
  }
  .task-input-row {
    max-width: 98vw;
  }
