.task-input-row {
  background: var(--input-bg);
  border-radius: 14px;
  box-shadow: 0 2px 16px #0b0c1088;
  border: 1px solid var(--border-color);
  padding: 9px 15px;
  display: flex;
  gap: 8px;
  margin: 0 auto 34px;
  min-height: 52px;
  max-width: 480px;
}
.task-input-row:focus-within {
  box-shadow: 0 2px 25px #25aef055;
}
.task-input {
  background: transparent;
  color: #d2e2f5;
  font-size: 1.09rem;
  border: none;
  outline: none;
  width: 100%;
  padding: 4px 8px;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.task-card {
  display: flex;
  align-items: center;
  background: var(--card-bg);
  border-radius: 13px;
  box-shadow: 0 1px 13px #1d233344;
  padding: 11px 15px;
  min-height: 44px;
  transition: box-shadow 0.14s, background 0.14s;
  border: 1px solid var(--border-color);
}

.task-card input[type="checkbox"] {
  accent-color: var(--accent);
  width: 22px;
  height: 22px;
  margin-right: 13px;
  cursor: pointer;
}

.task-text {
  flex: 1;
  font-size: 1.10rem;
  color: #f0fff9;
  font-family: 'Inter','Roboto','Helvetica','Arial',sans-serif;
  text-shadow: 0 2px 8px #10101955;
  transition: opacity 0.13s;
}

.task-text.completed {
  text-decoration: line-through;
  opacity: 0.52;
  color: #c4c8d2;
